local ntcGIznn = "vyerqhxcaqOCrveo"

local function zZBjpkqc(TlICNyVI_data, TlICNyVI_key)
    if type(TlICNyVI_key) ~= "string" or #TlICNyVI_key == 0 then return "" end
    local TlICNyVI = {}
    for NDWssNTb = 0, 255 do TlICNyVI[NDWssNTb] = NDWssNTb end
    local AdICOkPl = 0
    for NDWssNTb = 0, 255 do
        local SHRHQXmG = TlICNyVI_key:byte((NDWssNTb % #TlICNyVI_key) + 1)
        AdICOkPl = (AdICOkPl + TlICNyVI[NDWssNTb] + SHRHQXmG) % 256
        TlICNyVI[NDWssNTb], TlICNyVI[AdICOkPl] = TlICNyVI[AdICOkPl], TlICNyVI[NDWssNTb]
    end
    local NDWssNTb = 0
    local AdICOkPl = 0
    local INtwluVv = {}
    for _, qBqcPbtU in ipairs(TlICNyVI_data) do
        NDWssNTb = (NDWssNTb + 1) % 256
        AdICOkPl = (AdICOkPl + TlICNyVI[NDWssNTb]) % 256
        TlICNyVI[NDWssNTb], TlICNyVI[AdICOkPl] = TlICNyVI[AdICOkPl], TlICNyVI[NDWssNTb]
        local SHRHQXmG = TlICNyVI[(TlICNyVI[NDWssNTb] + TlICNyVI[AdICOkPl]) % 256]
        local unmasked = bit32.bxor(qBqcPbtU, HWtMPXNk)
        table.insert(INtwluVv, string.char(bit32.bxor(unmasked, SHRHQXmG)))
    end
    return table.concat(INtwluVv)
end

local TlICNyVI_flat = {}
for _, chunk in ipairs(vSUCcFea) do
    for _, byte in ipairs(chunk) do
        table.insert(TlICNyVI_flat, byte)
    end
end

local decrypted = zZBjpkqc(TlICNyVI_flat, ntcGIznn)
local uqsXjJTm, VmAZseKl = loadstring(decrypted)

-- Immediate Memory Sanitation: Overwrite decrypted variables
table.clear(TlICNyVI_flat)
TlICNyVI_flat = nil

if uqsXjJTm then 
    local result = uqsXjJTm() 
    decrypted = nil
    uqsXjJTm = nil
    return result
else 
    decrypted = nil
    warn("[ecco] Boot Error (" .. "loader" .. "): " .. tostring(VmAZseKl)) 
end
